import{_ as d,a0 as n,w as a,s as p,I as s,x as t,a1 as i,A as o,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"怎么在 Linux 中运行 DOS 程序 | LCTT x X-CMD","titleTemplate":false,"description":"怎么在 Linux 中运行 DOS 程序 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎么在 Linux 中运行 DOS 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎么在 Linux 中运行 DOS 程序 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171019 How to run DOS programs in Linux","title":"怎么在 Linux 中运行 DOS 程序","tag":"201710","desc":""},"relativePath":"201710/20171019 How to run DOS programs in Linux.md","filePath":"[post].md"}'),u={name:"201710/20171019 How to run DOS programs in Linux.md"};function g(m,e,f,D,S,O){const l=n("Link");return a(),p("div",null,[e[34]||(e[34]=s("h1",{id:"怎么在-linux-中运行-dos-程序",tabindex:"-1"},[t("怎么在 Linux 中运行 DOS 程序 "),s("a",{class:"header-anchor",href:"#怎么在-linux-中运行-dos-程序","aria-label":"Permalink to “怎么在 Linux 中运行 DOS 程序”"},"​")],-1)),e[35]||(e[35]=s("blockquote",null,[s("p",null,"QEMU 和 FreeDOS 使得很容易在 Linux 中运行老的 DOS 程序")],-1)),e[36]||(e[36]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/code_computer_development_programming.png?itok=4OM29-82",alt:"How to run DOS programs in Linux",title:"How to run DOS programs in Linux"})],-1)),e[37]||(e[37]=s("p",null,"Image by : opensource.com",-1)),e[38]||(e[38]=s("p",null,"传统的 DOS 操作系统支持的许多非常优秀的应用程序： 文字处理，电子表格，游戏和其它的程序。但是一个应用程序太老了，并不意味着它没用了。",-1)),s("p",null,[e[1]||(e[1]=t("如今有很多理由去运行一个旧的 DOS 应用程序。或许是从一个遗留的业务应用程序中提取一个报告，或者是想玩一个经典的 DOS 游戏，或者只是因为你对“传统计算机”很好奇。你不需要去双引导你的系统去运行 DOS 程序。取而代之的是，你可以在 Linux 中在一个 PC 仿真程序和 ",-1)),i(l,{href:"http://www.freedos.org/"},{default:o(()=>[...e[0]||(e[0]=[t("FreeDOS",-1)])]),_:1}),e[2]||(e[2]=t(" 的帮助下去正确地运行它们。",-1))]),e[39]||(e[39]=s("p",null,"FreeDOS 是一个完整的、免费的、DOS 兼容的操作系统，你可以用它来玩经典的游戏、运行旧式业务软件，或者开发嵌入式系统。任何工作在 MS-DOS 中的程序也可以运行在 FreeDOS 中。",-1)),s("p",null,[e[4]||(e[4]=t("在那些“过去的时光”里，你安装的 DOS 是作为一台计算机上的独占操作系统。 而现今，它可以很容易地安装到 Linux 上运行的一台虚拟机中。 ",-1)),i(l,{href:"https://www.qemu.org/"},{default:o(()=>[...e[3]||(e[3]=[t("QEMU",-1)])]),_:1}),e[5]||(e[5]=t(" （",-1)),e[6]||(e[6]=s("ruby",null,[t("快速仿真程序"),s("rt",null,"Quick EMUlator")],-1)),e[7]||(e[7]=t("的缩写） 是一个开源的虚拟机软件，它可以在 Linux 中以一个“",-1)),e[8]||(e[8]=s("ruby",null,[t("访客"),s("rt",null,"guest")],-1)),e[9]||(e[9]=t("”操作系统来运行 DOS。许多流行的 Linux 系统都默认包含了 QEMU 。",-1))]),e[40]||(e[40]=r('<p>通过以下四步，很容易地在 Linux 下通过使用 QEMU 和 FreeDOS 去运行一个老的 DOS 程序。</p><h3 id="第-1-步-设置一个虚拟磁盘" tabindex="-1">第 1 步：设置一个虚拟磁盘 <a class="header-anchor" href="#第-1-步-设置一个虚拟磁盘" aria-label="Permalink to “第 1 步：设置一个虚拟磁盘”">​</a></h3><p>你需要一个地方来在 QEMU 中安装 FreeDOS，为此你需要一个虚拟的 C: 驱动器。在 DOS 中，字母<code>A:</code> 和 <code>B:</code> 是分配给第一和第二个软盘驱动器的，而 <code>C:</code> 是第一个硬盘驱动器。其它介质，包括其它硬盘驱动器和 CD-ROM 驱动器，依次分配 <code>D:</code>、<code>E:</code> 等等。</p><p>在 QEMU 中，虚拟磁盘是一个镜像文件。要初始化一个用做虚拟 <code>C: </code> 驱动器的文件，使用 <code>qemu-img</code> 命令。要创建一个大约 200 MB 的镜像文件，可以这样输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-img create dos.img 200M</span></span></code></pre></div><p>与现代计算机相比， 200MB 看起来非常小，但是早在 1990 年代， 200MB 是非常大的。它足够安装和运行 DOS。</p><h3 id="第-2-步-qemu-选项" tabindex="-1">第 2 步： QEMU 选项 <a class="header-anchor" href="#第-2-步-qemu-选项" aria-label="Permalink to “第 2 步： QEMU 选项”">​</a></h3><p>与 PC 仿真系统 VMware 或 VirtualBox 不同，你需要通过 QEMU 命令去增加每个虚拟机的组件来 “构建” 你的虚拟系统 。虽然，这可能看起来很费力，但它实际并不困难。这些是我们在 QEMU 中用于去引导 FreeDOS 的参数：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><code>qemu-system-i386</code></td><td style="text-align:left;">QEMU 可以仿真几种不同的系统，但是要引导到 DOS，我们需要有一个 Intel 兼容的 CPU。 为此，使用 i386 命令启动 QEMU。</td></tr><tr><td style="text-align:left;"><code>-m 16</code></td><td style="text-align:left;">我喜欢定义一个使用 16MB 内存的虚拟机。它看起来很小，但是 DOS 工作不需要很多的内存。在 DOS 时代，计算机使用 16MB 或者 8MB 内存是非常普遍的。</td></tr><tr><td style="text-align:left;"><code>-k en-us</code></td><td style="text-align:left;">从技术上说，这个 <code>-k</code> 选项是不需要的，因为 QEMU 会设置虚拟键盘去匹配你的真实键盘（在我的例子中， 它是标准的 US 布局的英语键盘）。但是我还是喜欢去指定它。</td></tr><tr><td style="text-align:left;"><code>-rtc base=localtime</code></td><td style="text-align:left;">每个传统的 PC 设备有一个实时时钟 (RTC) 以便于系统可以保持跟踪时间。我发现它是设置虚拟 RTC 匹配你的本地时间的最简单的方法。</td></tr><tr><td style="text-align:left;"><code>-soundhw sb16,adlib,pcspk</code></td><td style="text-align:left;">如果你需要声音，尤其是为了玩游戏时，我更喜欢定义 QEMU 支持 SoundBlaster 16 声音硬件和 AdLib 音乐。SoundBlaster 16 和 AdLib 是在 DOS 时代非常常见的声音硬件。一些老的程序也许使用 PC 喇叭发声； QEMU 也可以仿真这个。</td></tr><tr><td style="text-align:left;"><code>-device cirrus-vga</code></td><td style="text-align:left;">要使用图像，我喜欢去仿真一个简单的 VGA 视频卡。Cirrus VGA 卡是那时比较常见的图形卡, QEMU 可以仿真它。</td></tr><tr><td style="text-align:left;"><code>-display gtk</code></td><td style="text-align:left;">对于虚拟显示，我设置 QEMU 去使用 GTK toolkit，它可以将虚拟系统放到它自己的窗口内，并且提供一个简单的菜单去控制虚拟机。</td></tr><tr><td style="text-align:left;"><code>-boot order=</code></td><td style="text-align:left;">你可以告诉 QEMU 从多个引导源来引导虚拟机。从软盘驱动器引导（在 DOS 机器中一般情况下是 <code>A:</code> ）指定 <code>order=a</code>。 从第一个硬盘驱动器引导（一般称为 <code>C:</code>） 使用 <code>order=c</code>。 或者去从一个 CD-ROM 驱动器（在 DOS 中经常分配为 <code>D:</code> ） 使用 <code>order=d</code>。 你可以使用组合字母去指定一个特定的引导顺序， 比如 <code>order=dc</code> 去第一个使用 CD-ROM 驱动器，如果 CD-ROM 驱动器中没有引导介质，然后使用硬盘驱动器。</td></tr></tbody></table></div><h3 id="第-3-步-引导和安装-freedos" tabindex="-1">第 3 步： 引导和安装 FreeDOS <a class="header-anchor" href="#第-3-步-引导和安装-freedos" aria-label="Permalink to “第 3 步： 引导和安装 FreeDOS”">​</a></h3><p>现在 QEMU 已经设置好运行虚拟机，我们需要一个 DOS 系统来在那台虚拟机中安装和引导。 FreeDOS 做这个很容易。它的最新版本是 FreeDOS 1.2， 发行于 2016 年 12 月。</p>',11)),s("p",null,[e[11]||(e[11]=t("从 ",-1)),i(l,{href:"http://www.freedos.org/"},{default:o(()=>[...e[10]||(e[10]=[t("FreeDOS 网站",-1)])]),_:1}),e[12]||(e[12]=t("上下载 FreeDOS 1.2 的发行版。 FreeDOS 1.2 CD-ROM “standard” 安装器 （",-1)),e[13]||(e[13]=s("code",null,"FD12CD.iso",-1)),e[14]||(e[14]=t("） 可以很好地在 QEMU 上运行，因此，我推荐使用这个版本。",-1))]),e[41]||(e[41]=r('<p>安装 FreeDOS 很简单。首先，告诉 QEMU 使用 CD-ROM 镜像并从其引导。 记住，第一个硬盘驱动器是 <code>C:</code> 驱动器，因此， CD-ROM 将以 <code>D:</code> 驱动器出现。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-system-i386 -m 16 -k en-us -rtc base=localtime -soundhw sb16,adlib -device cirrus-vga -display gtk -hda dos.img -cdrom FD12CD.iso -boot order=d</span></span></code></pre></div><p>正如下面的提示，你将在几分钟内安装完成 FreeDOS 。</p><p><img src="https://opensource.com/sites/default/files/u128651/install1a.png" alt="Starting FreeDOS installation" title="Starting FreeDOS installation"></p><p><img src="https://opensource.com/sites/default/files/u128651/install2_0.png" alt="Select your keyboard layout" title="Select your keyboard layout"></p><p><img src="https://opensource.com/sites/default/files/u128651/install3.png" alt="Selecting which packages to install" title="Selecting which packages to install"></p><p><img src="https://opensource.com/sites/default/files/u128651/install4.png" alt="Rebooting after installation" title="Rebooting after installation"></p><p>在你安装完成之后，关闭窗口退出 QEMU。</p><h3 id="第-4-步-安装并运行你的-dos-应用程序" tabindex="-1">第 4 步：安装并运行你的 DOS 应用程序 <a class="header-anchor" href="#第-4-步-安装并运行你的-dos-应用程序" aria-label="Permalink to “第 4 步：安装并运行你的 DOS 应用程序”">​</a></h3>',9)),s("p",null,[e[16]||(e[16]=t("一旦安装完 FreeDOS，你可以在 QEMU 中运行各种 DOS 应用程序。你可以在线上通过各种档案文件或其它",-1)),i(l,{href:"http://www.freedos.org/links/"},{default:o(()=>[...e[15]||(e[15]=[t("网站",-1)])]),_:1}),e[17]||(e[17]=t("找到老的 DOS 程序。",-1))]),e[42]||(e[42]=r('<p>QEMU 提供了一个在 Linux 上访问本地文件的简单方法。比如说，想去用 QEMU 共享 <code>dosfiles/</code> 文件夹。 通过使用 <code>-drive</code> 选项，简单地告诉 QEMU 去使用这个文件夹作为虚拟的 FAT 驱动器。 QEMU 将像一个硬盘驱动器一样访问这个文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-drive file=fat:rw:dosfiles/</span></span></code></pre></div><p>现在，你可以使用合适的选项去启动 QEMU，加上一个外部的虚拟 FAT 驱动器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-system-i386 -m 16 -k en-us -rtc base=localtime -soundhw sb16,adlib -device cirrus-vga -display gtk -hda dos.img -drive file=fat:rw:dosfiles/ -boot order=c</span></span></code></pre></div><p>一旦你引导进入 FreeDOS，你保存在 <code>D:</code> 驱动器中的任何文件将被保存到 Linux 上的 <code>dosfiles/</code> 文件夹中。可以从 Linux 上很容易地直接去读取该文件；然而，必须注意的是，启动 QEMU 后，不能从 Linux 中去改变 <code>dosfiles/</code> 这个文件夹。 当你启动 QEMU 时，QEMU 一次性构建一个虚拟的 FAT 表，如果你在启动 QEMU 之后，在 <code>dosfiles/</code> 文件夹中增加或删除文件，仿真程序可能会很困惑。</p><p>我使用 QEMU 像这样运行一些我收藏的 DOS 程序， 比如 As-Easy-As 电子表格程序。这是一个在上世纪八九十年代非常流行的电子表格程序，它和现在的 Microsoft Excel 和 LibreOffice Calc 或和以前更昂贵的 Lotus 1-2-3 电子表格程序完成的工作是一样的。 As-Easy-As 和 Lotus 1-2-3 都保存数据为 WKS 文件，最新版本的 Microsoft Excel 不能读取它，但是，根据兼容性， LibreOffice Calc 可以支持它。</p><p><img src="https://opensource.com/sites/default/files/u128651/aseasy-regress1.png" alt="As-Easy-As spreadsheet program" title="As-Easy-As spreadsheet program"></p><p><em>As-Easy-As 电子表格程序</em></p><p>我也喜欢在 QEMU中引导 FreeDOS 去玩一些收藏的 DOS 游戏，比如原版的 Doom。这些老的 DOS 游戏玩起来仍然非常有趣， 并且它们现在在 QEMU 上运行的非常好。</p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-doom.png" alt="Doom" title="Doom"></p><p><em>Doom</em></p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-heretic.png" alt="Heretic" title="Heretic"></p><p><em>Heretic</em></p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-jill.png" alt="Jill of the Jungle" title="Jill of the Jungle"></p><p><em>Jill of the Jungle</em></p><p><img src="https://opensource.com/sites/default/files/u128651/qemu-keen.png" alt="Commander Keen" title="Commander Keen"></p><p><em>Commander Keen</em></p><p>QEMU 和 FreeDOS 使得在 Linux 上运行老的 DOS 程序变得很容易。你一旦设置好了 QEMU 作为虚拟机仿真程序并安装了 FreeDOS，你将可以在 Linux 上运行你收藏的经典的 DOS 程序。</p>',18)),s("p",null,[s("em",null,[e[19]||(e[19]=t("所有图片要致谢 ",-1)),i(l,{href:"http://www.freedos.org/"},{default:o(()=>[...e[18]||(e[18]=[t("FreeDOS.org",-1)])]),_:1}),e[20]||(e[20]=t("。",-1))])]),e[43]||(e[43]=s("hr",null,null,-1)),e[44]||(e[44]=s("p",null,"作者简介：",-1)),e[45]||(e[45]=s("p",null,"Jim Hall 是一位开源软件的开发者和支持者，可能最广为人知的是他是 FreeDOS 的创始人和项目协调者。 Jim 也非常活跃于开源软件适用性领域，作为 GNOME Outreachy 适用性测试的导师，同时也作为一名兼职教授，教授一些开源软件适用性的课程，从 2016 到 2017， Jim 在 GNOME 基金会的董事会担任董事，在工作中， Jim 是本地政府部门的 CIO。",-1)),e[46]||(e[46]=s("hr",null,null,-1)),s("p",null,[e[22]||(e[22]=t("via: ",-1)),i(l,{href:"https://opensource.com/article/17/10/run-dos-applications-linux"},{default:o(()=>[...e[21]||(e[21]=[t("https://opensource.com/article/17/10/run-dos-applications-linux",-1)])]),_:1})]),s("p",null,[e[26]||(e[26]=t("作者：",-1)),i(l,{href:"https://opensource.com/users/jim-hall"},{default:o(()=>[...e[23]||(e[23]=[t("Jim Hall",-1)])]),_:1}),e[27]||(e[27]=t(" 译者：",-1)),i(l,{href:"https://github.com/qhwdw"},{default:o(()=>[...e[24]||(e[24]=[t("qhwdw",-1)])]),_:1}),e[28]||(e[28]=t(" 校对：",-1)),i(l,{href:"https://github.com/wxy"},{default:o(()=>[...e[25]||(e[25]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[31]||(e[31]=t("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[29]||(e[29]=[t("LCTT",-1)])]),_:1}),e[32]||(e[32]=t(" 原创编译，",-1)),i(l,{href:"https://linux.cn/"},{default:o(()=>[...e[30]||(e[30]=[t("Linux中国",-1)])]),_:1}),e[33]||(e[33]=t(" 荣誉推出",-1))])])}const M=d(u,[["render",g]]);export{k as __pageData,M as default};
